".hero-massive-title {
  --keyword-height: clamp(6.5rem, 10vw, 8.5rem);
  max-width: none;
  margin: 0;
  display: inline-flex;
  flex-direction: column;
  align-items: stretch;
  width: fit-content;
  max-width: 100%;
  text-align: left;
  font-family: var(--sans);
  font-size: clamp(3.2rem, 6.5vw, 5.5rem);
  font-weight: 800;
  line-height: 1.02;
  letter-spacing: -0.04em;
  color: #fff;
  text-transform: uppercase;
  margin-bottom: 10px;
  text-shadow: 0 0 45px rgba(0, 242, 254, 0.18), 0 24px 80px rgba(0, 0, 0, 0.25);
}

.hero-massive-title em {
  display: inline-block;
  animation: heartbeat 1.8s ease-in-out infinite;
}

.title-line {
  display: inline-flex;
  align-items: center;
  gap: 0.8rem;
  opacity: 0;
  animation: heroTextReveal 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  transform-origin: center center;
  white-space: nowrap;
}

.text-video-title {
  display: inline-block;
  font-size: 1em;
  line-height: inherit;
  width: auto;
  min-width: 0;
  white-space: nowrap;
}

/* Row 1 sets width; row 2 sits directly below without overlapping */
.title-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  overflow: visible;
}

.title-row:last-child {
  width: 100%;
  margin-top: 0.1em;
}

.hero-keyword-slot {
  flex: 1 1 0;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  min-width: 0;
  overflow: visible;
}

.single-line {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  width: max-content;
  white-space: nowrap;
}

.title-base {
  display: inline-block;
  white-space: nowrap;
  font-weight: 900;
}

.hero-massive-title.centered {
  align-items: center;
  text-align: center;
}

.hero-keyword-image {
  display: block;
  height: var(--keyword-height);
  width: auto;
  max-width: none;
  max-height: var(--keyword-height);
  flex-shrink: 0;
  object-fit: contain;
  object-position: left center;
  vertical-align: middle;
  margin-block: -1.2rem;
}

